function mesh(geo,mat,parent,pos){const m=new THREE.Mesh(geo,mat);m.castShadow=true;m.receiveShadow=true;if(pos)m.position.copy(V(pos));parent?.add(m);return m}
function box(parent,size,pos,mat=metal){return mesh(new THREE.BoxGeometry(...size),mat,parent,pos)}
function cylinder(parent,a,b,r,mat=metal,inner=0){a=V(a);b=V(b);const len=a.distanceTo(b);let geo;if(inner){const s=new THREE.Shape();s.absarc(0,0,r,0,Math.PI*2,false);const h=new THREE.Path();h.absarc(0,0,inner,0,Math.PI*2,true);s.holes.push(h);geo=new THREE.ExtrudeGeometry(s,{depth:len,bevelEnabled:false,steps:1,curveSegments:24});geo.translate(0,0,-len/2);smoothTube(geo);geo.rotateX(Math.PI/2)}else geo=new THREE.CylinderGeometry(r,r,len,24);const m=mesh(geo,mat,parent);m.position.copy(a.clone().add(b).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),b.clone().sub(a).normalize());return m}
function smoothTube(geo){const p=geo.attributes.position,n=geo.attributes.normal;for(let i=0;i<p.count;i++)if(Math.abs(n.getZ(i))<.01){const x=p.getX(i),y=p.getY(i),r=Math.hypot(x,y);if(r){const s=x*n.getX(i)+y*n.getY(i)<0?-1:1;n.setXYZ(i,s*x/r,s*y/r,0)}}n.needsUpdate=true;}
function tubeSquare(parent,a,b,w,mat=metal){const s=new THREE.Shape();s.moveTo(-w/2,-w/2);s.lineTo(w/2,-w/2);s.lineTo(w/2,w/2);s.lineTo(-w/2,w/2);s.closePath();const h=new THREE.Path();const k=w/2-.001;h.moveTo(-k,-k);h.lineTo(-k,k);h.lineTo(k,k);h.lineTo(k,-k);h.closePath();s.holes.push(h);const av=V(a),bv=V(b),l=av.distanceTo(bv);const geo=new THREE.ExtrudeGeometry(s,{depth:l,bevelEnabled:false,steps:1});geo.translate(0,0,-l/2);const m=mesh(geo,mat,parent);m.position.copy(av.add(bv).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),V(b).sub(V(a)).normalize());return m}
