 const clip=(poly,sg)=>{const r=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],da=sg*(a[0]-axis),db=sg*(b[0]-axis);if(da>=-1e-10)r.push(a);if((da>1e-10&&db< -1e-10)||(da< -1e-10&&db>1e-10))r.push(mix(a,b,da/(da-db)));}return r};
 for(let i=0;i<pos.count;i+=3){const tri=[0,1,2].map(j=>[pos.getX(i+j),pos.getY(i+j),pos.getZ(i+j),uv.getX(i+j),uv.getY(i+j)]);for(const sg of [-1,1]){const poly=clip(tri,sg);for(let j=1;j+1<poly.length;j++){const a=poly[0],b=poly[j],c=poly[j+1];const cross=new THREE.Vector3(...b.slice(0,3)).sub(V(a.slice(0,3))).cross(V(c.slice(0,3)).sub(V(a.slice(0,3))));if(cross.lengthSq()<1e-20)continue;for(const v of [a,b,c]){out.push(...v.slice(0,3));tex.push(...v.slice(3));}}}}
