function warpSail(geo,p,center,depth){const a=geo.attributes.position,flat=geo.userData.flat,d=p.development;if(!d)return;const mix=Math.min(1,depth/.270);for(let i=0;i<a.count;i++){const x=flat[i*3],y=flat[i*3+1],z=flat[i*3+2],u=x+center.x,v=y+center.y,E=V(u<0?d.Eminus:d.Eplus),A=V(d.A);const n=E.clone().multiplyScalar(u<0?-1:1).cross(A).normalize().multiplyScalar(d.sg);const q=V(d.C).addScaledVector(A,v).addScaledVector(E,Math.abs(u)).addScaledVector(n,z-(d.innerOffsetMm||0)/1000);a.setXYZ(i,x+(q.x-center.x-x)*mix,y+(q.y-center.y-y)*mix,z+(q.z-z)*mix);}a.needsUpdate=true;geo.computeVertexNormals();geo.computeBoundingSphere();geo.computeBoundingBox();}

function updateSail(depth){if(Math.abs(updateSail.last-depth)<1e-7)return;updateSail.last=depth;for(const m of sailMeshes){warpSail(m.geometry,m.geometry.userData.part,m.geometry.userData.center,depth);for(const e of m.children.filter(c=>c.type==='LineSegments')){e.geometry.dispose();e.geometry=new THREE.EdgesGeometry(m.geometry,.5);}}for(const m of sailTraces){warpSail(m.geometry,m.geometry.userData.part,m.geometry.userData.center,depth);}}
