 // The textile sleeve wraps the return, and a clamp plate retains its tail.
 box(g,[.001,.026,.020],[side*.0065,0,-.028],side<0?studyMats.hook:studyMats.loop);box(g,[.002,.030,.012],[side*.008,0,-.028],studyMats.carrier);
 for(const xx of [.019,.049]){ring(g,[side*xx,0,.004],.009,.0021,.001,nylon,'z');cylinder(g,[side*xx,0,-.013],[side*xx,0,.008],.002,nylon);}
