function readHash(){try{const raw=new URLSearchParams(location.hash.slice(1)).get('vista');if(!raw)return;const s=JSON.parse(raw);if(s.v!==1)return;if(Number.isFinite(s.depth)){sailDepth=Math.max(0,Math.min(.3,s.depth));$('#sail-depth').value=sailDepth*1000;$('#sail-value').textContent=Math.round(sailDepth*1000)+' mm';buildStudyAssembly()}studyInspect=!!s.inside;if(['workshop','render'].includes(s.m))setMode(s.m);t=Math.max(0,Math.min(5,Number(s.t)||0));explosion=clamp(Number(s.e)||0);separation=clamp(Number(s.s)||0);$('#explode').value=explosion;$('#separate').value=separation;$('#interior').checked=!!s.i;$('#flag').checked=s.f!==false;$('#piece-labels').checked=!!s.l;if(DETAIL_INFO[s.d]){openDetail(s.d);explosion=clamp(Number(s.e)||0);$('#explode').value=explosion;}if(s.c?.length===3&&s.target?.length===3&&[...s.c,...s.target].every(Number.isFinite)){camera.position.copy(V(s.c));controls.target.copy(V(s.target));camTween=null;readHash.camera=true}}catch{toast('No se pudo recuperar la vista; se muestra el barco completo.')}}
